// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  AbsoluteFill,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Module-level font loading — delayRender/continueRender handled internally
const { fontFamily: interFamily } = loadInter();



export type AgeTimelineProps = Record<string, any>;

const AgeTimeline: React.FC<AgeTimelineProps> = ({
  backgroundColor = "#0F172A", // Slate 900
  transparentBackground = false,
  durationInSeconds = 6,
  primaryColor = "#3B82F6", // Blue 500
  inactiveColor = "#334155", // Slate 700
  textColor = "#F8FAFC", // Slate 50
  milestones = ["20", "30", "40", "50", "💪 Still strong"],
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground
    ? `${backgroundColor}00`
    : backgroundColor;
  
  // Responsive baseline
  const s = Math.min(width, height);

  // Animation layout math
  const safeMilestones = milestones.length > 1 ? milestones : ["Start", "End"];
  const totalSegments = safeMilestones.length - 1;
  const framesPerSegment = 30; // 1 second per segment at 30fps
  const totalTravelTime = totalSegments * framesPerSegment;

  // Track progress calculation
  const trackProgress = interpolate(frame, [0, totalTravelTime], [0, 100], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const nodeSize = s * 0.04;
  const trackHeight = s * 0.01;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: interFamily,
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      {/* Main Timeline Container */}
      <div
        style={{
          width: "80%",
          position: "relative",
          display: "flex",
          alignItems: "center",
        }}
      >
        {/* Inactive Background Track */}
        <div
          style={{
            position: "absolute",
            left: nodeSize / 2,
            right: nodeSize / 2,
            height: trackHeight,
            backgroundColor: inactiveColor,
            borderRadius: trackHeight / 2,
            zIndex: 0,
          }}
        />

        {/* Active Animated Track Wrapper */}
        <div
          style={{
            position: "absolute",
            left: nodeSize / 2,
            right: nodeSize / 2,
            height: trackHeight,
            zIndex: 1,
            display: "flex",
            alignItems: "center",
            overflow: "hidden", // Ensures fill corners follow wrapper radius
            borderRadius: trackHeight / 2,
          }}
        >
          <div
            style={{
              width: `${trackProgress}%`,
              height: "100%",
              backgroundColor: primaryColor,
              boxShadow: `0 0 ${s * 0.02}px ${primaryColor}80`,
              transition: "none",
            }}
          />
        </div>

        {/* Timeline Nodes */}
        <div
          style={{
            width: "100%",
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
            position: "relative",
            zIndex: 10,
          }}
        >
          {safeMilestones.map((text, i) => {
            const activationFrame = i * framesPerSegment;
            const isFinal = i === safeMilestones.length - 1;

            const activeScale = spring({
              frame: frame - activationFrame,
              fps,
              config: { damping: isFinal ? 10 : 14, mass: 0.8 },
            });

            const textOpacity = interpolate(
              frame,
              [activationFrame, activationFrame + 15],
              [0, 1],
              { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
            );

            const textY = interpolate(
              frame,
              [activationFrame, activationFrame + 20],
              [20, 0],
              { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
            );

            return (
              <div
                key={`node-${i}`}
                style={{
                  position: "relative",
                  display: "flex",
                  flexDirection: "column",
                  alignItems: "center",
                }}
              >
                {/* Node Inactive Base */}
                <div
                  style={{
                    width: nodeSize,
                    height: nodeSize,
                    borderRadius: "50%",
                    backgroundColor: inactiveColor,
                  }}
                />

                {/* Node Active Overlay */}
                <div
                  style={{
                    position: "absolute",
                    top: 0,
                    width: nodeSize,
                    height: nodeSize,
                    borderRadius: "50%",
                    backgroundColor: primaryColor,
                    transform: `scale(${activeScale})`,
                    boxShadow: `0 0 ${s * 0.02}px ${primaryColor}A0`,
                    transition: "none",
                  }}
                />

                {/* Label Text */}
                <div
                  style={{
                    position: "absolute",
                    top: nodeSize + s * 0.03,
                    left: "50%",
                    whiteSpace: "nowrap",
                    opacity: textOpacity,
                    transform: `translate(-50%, ${textY}px)`,
                    color: textColor,
                    fontSize: isFinal ? s * 0.05 : s * 0.04,
                    fontWeight: isFinal ? 800 : 600,
                    textShadow: `0 4px 12px rgba(0,0,0,0.5)`,
                    transition: "none",
                  }}
                >
                  {text}
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default AgeTimeline;